import math

def is_simple_power(x: float, n: float) -> bool:
    if n == 0:
        return x == 0
    if n == 1:
        return x == 1

    if x == 1:
        return True

    if x == 0:
        return False

    if n > 0:
        if n < 1:
            k = math.log(x) / math.log(n)
            if k.is_integer():
                return True
        else:
            k = math.log(x) / math.log(n)
            if k.is_integer() and k >= 0:
                return True
            if x * n == 1:
                return True
    else:
        abs_x = abs(x)
        abs_n = abs(n)
        k = math.log(abs_x) / math.log(abs_n)
        if k.is_integer():
            if x > 0 and k % 2 == 0:
                return True
            elif x < 0 and k % 2 == 1:
                return True
        if abs_x * abs_n == 1:
            return (x > 0 and abs_n % 2 == 0) or (x < 0 and abs_n % 2 == 1)

    for k in range(0, 1000):
        current = n ** k
        if current == x:
            return True
        current = n ** (-k - 1)
        if current == x:
            return True
    return False

