from typing import List, Dict

def histogram(test: str) -> Dict[str, int]:
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    1. **Input Parsing**: Split the input string into individual letters, handling spaces and edge cases like empty input.
    2. **Frequency Counting**: Count occurrences of each letter in the list.
    3. **Determine Maximum Frequency**: Find the highest occurrence value efficiently.
    4. **Collect Maximum Frequency Letters**: Gather all letters with the maximum frequency, including handling ties.
    5. **Edge Case Handling**: Correctly manage scenarios such as empty input and uniform counts.
    """
    letters = test.split()
    if not letters:
        return {}

    frequency = {}
    for letter in letters:
        frequency[letter] = frequency.get(letter, 0) + 1

    max_count = max(frequency.values(), default=0)
    return {k: v for k, v in frequency.items() if v == max_count}

