from typing import List

def valid_date(date: str) -> bool:
    """
    Validates a date string in the format mm-dd-yyyy.

    Args:
    date (str): The date string to be validated.

    Returns:
    bool: True if the date is valid, False otherwise.
    """

    # Check if the input is not empty
    if not date:
        return False

    # Split the date string into parts
    parts = date.split('-')

    # Check if there are exactly 3 parts
    if len(parts) != 3:
        return False

    # Check if each part has the correct number of digits
    if len(parts[0]) != 2 or len(parts[1]) != 2 or len(parts[2]) != 4:
        return False

    # Convert parts to integers
    try:
        month = int(parts[0])
        day = int(parts[1])
        year = int(parts[2])
    except ValueError:
        return False

    # Check if month is between 1 and 12
    if month < 1 or month > 12:
        return False

    # Define the maximum days for each month
    max_days = {
        1: 31, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31
    }

    # Check if day is within the valid range for the given month
    if month == 2:
        if day < 1 or day > 29:
            return False
    else:
        if month in max_days:
            if day < 1 or day > max_days[month]:
                return False
        else:
            return False

    # Check if the year is a positive number
    if year < 1:
        return False

    # If all checks pass, the date is valid
    return True

