def is_sorted(lst: List[int]) -> bool:
    """
    Given a list of non-negative integers, return whether or not they are sorted
    in ascending order. If the list has more than one duplicate of the same number, return False.
    """
    # Check if the list is sorted in non-decreasing order
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False

    # Check for more than two occurrences of any number
    counts = {}
    for num in lst:
        counts[num] = counts.get(num, 0) + 1
        if counts[num] > 2:
            return False

    return True

