from typing import List

def tri(n: int) -> List[int]:
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    # Initialize the list with base cases
    tribonacci = [1, 3]  # tri(0) = 1, tri(1) = 3

    # Generate the sequence up to n
    for i in range(2, n + 1):
        if i % 2 == 0:
            # Even index: 1 + (i // 2)
            tribonacci.append(1 + (i // 2))
        else:
            # Odd index: tri(i-1) + tri(i-2) + (1 + ((i+1) // 2))
            next_even = 1 + ((i + 1) // 2)
            tribonacci.append(tribonacci[i-1] + tribonacci[i-2] + next_even)

    # Handle the case when n is 0 (only tri(0) is needed)
    if n == 0:
        return [1]

    return tribonacci[:n+1]

