def is_nested(string):
    stack = []
    max_depth = 0
    current_depth = 0
    for c in string:
        if c == '(':
            stack.append(c)
            current_depth = len(stack)
            if current_depth > max_depth:
                max_depth = current_depth
        elif c == ')':
            if not stack:
                return False  # invalid
            stack.pop()
