def compare_one(a: Union[int, float, str], b: Union[int, float, str]) -> Union[int, float, str, None]:
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """
    def to_float(value: Union[int, float, str]) -> float:
        if isinstance(value, (int, float)):
            return float(value)
        # Handle string representations
        value = value.replace(',', '.')
        try:
            return float(value)
        except ValueError:
            raise ValueError(f"Invalid numeric string: {value}")

    # Convert both values to floats for comparison
    try:
        a_float = to_float(a)
        b_float = to_float(b)
    except ValueError:
        raise ValueError("Invalid input types or values")

    if a_float > b_float:
        return a
    elif b_float > a_float:
        return b
    else:
        return None

