from typing import List

def fix_spaces(text: str) -> str:
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    >>> fix_spaces("Example")
    "Example"
    >>> fix_spaces("Example 1")
    "Example_1"
    >>> fix_spaces(" Example 2")
    "_Example_2"
    >>> fix_spaces(" Example   3")
    "_Example-3"
    """
    result = []
    current_group = []
    current_is_space = None

    for char in text:
        if char == ' ':
            if current_is_space is False:
                # Transition to space group
                if current_group:
                    result.append(''.join(current_group))
                    current_group = []
                current_is_space = True
                current_group.append(char)
            else:
                current_group.append(char)
        else:
            if current_is_space is True:
                # Transition to non-space group
                if current_group:
                    result.append(''.join(current_group))
                    current_group = []
                current_is_space = False
                current_group.append(char)
            else:
                current_group.append(char)

    if current_group:
        result.append(''.join(current_group))

    # Process the result list to replace space groups
    processed = []
    for group in result:
        if group[0] == ' ':
            if len(group) > 2:
                processed.append('-')
            else:
                processed.append('_' * len(group))
        else:
            processed.append(group)

    return ''.join(processed)

